58023274553453,"created_at":"","operations":[{"id":"b8f21efd-d986-49e3-959b-e200b8d53794","type":"select","data":{"title":"Select Advancement","modeType":"PREDEFINED","optionType":"CUSTOM","optionsPredefined":[{"id":"d243dc01-803f-4252-86e7-4959b6eac200","type":"CUSTOM","title":"- Not Yet","description":"No next advancement yet.","operations":[]},{"id":"07ac7c4c-495c-4376-a1a4-27c87e2727cc","type":"CUSTOM","title":"Mature","description":"When you advance a young animal companion to a mature animal companion:\n\n*   If your companion is Medium or smaller, it grows by one size.\n    \n*   Increase its Strength, Dexterity, Constitution, and Wisdom modifiers by 1.\n    \n*   Increase its proficiency rank for Perception and all saving throws to expert. Increase its proficiency ranks in Intimidation, Stealth, and Survival to trained, and if it was already trained in one of those skills from its type, increase its proficiency rank in that skill to expert.\n    \n*   Increase its unarmed attack damage from one die to two dice (for instance 1d8 to 2d8)","operations":[{"id":"84e005c3-8a05-41f1-acad-a5688ee74c4f","type":"giveAbilityBlock","data":{"type":"feat","abilityBlockId":40304}}]}]}}],"name":"Next Advancement","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"You advance an animal companion, usually due to one of your class feat choices.","special":"","type":"action","meta_data":{},"traits":[],"content_source_id":16,"version":"1.0"},{"id":4302541392659529,"created_at":"","operations":[{"id":"9921ac76-0334-48bd-b661-0209da83b4dd","type":"adjValue","data":{"variable":"SENSES_IMPRECISE","value":"motion sense, 30"}}],"name":"Motion Sense","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"Your oozeform chair can sense nearby creatures through vibration in the air. This is an imprecise sense with a range of 30 feet.","special":"","type":"sense","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":3725444017242910,"created_at":"","operations":[],"name":"Mount","actions":null,"level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"","access":"","description":"This companion is especially suited for riding and ignores the restrictions against using non-land Speeds and moving and Supporting you on the same turn while it is carrying a rider.","special":"","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":7902105097017992,"created_at":"","operations":[],"name":"Support","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"The creature is an animal companion.","access":"","description":"A pseudopod extends out from your chair, retrieving an unattended object within 15 feet. If you don't have a hand free to receive the object, the chair drops it in your space.","special":"If the animal uses the Support action, the only other actions it can use on this turn are basic [move](link_trait_1505) actions to get into position to take advantage of the Support benefits; if it has already used any other action this turn, it can’t Support you.","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"},{"id":4322909037039800,"created_at":"","operations":[],"name":"Extend Pseudopod","actions":"ONE-ACTION","level":1,"rarity":"COMMON","prerequisites":[],"frequency":"","cost":"","trigger":"","requirements":"Your companion has learned its advanced maneuver through nimble or savage advancement.","access":"","description":"Your chair lengthens itself, granting its pseudopod [Strike](link_action_19856) the [reach 10 feet](link_trait_4173) trait until the beginning of your next turn.","special":"","type":"action","meta_data":{"source":{"book":"Treasure Vault (Remastered)","page":"107","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"traits":[],"content_source_id":16,"version":"1.0"}],"spells":null,"deprecated":false,"abilities_added":[],"experience":0,"hp_current":0,"hp_temp":0,"stamina_current":0,"resolve_current":0,"operation_data":null,"type":"creature"},"item":{"name":"Animal Pseudopod","bulk":null,"level":0,"rarity":"COMMON","description":"An [agile](link_trait_1569) pseudopod attack.","group":"WEAPON","hands":null,"size":"MEDIUM","craft_requirements":"","usage":"","meta_data":{"bulk":{},"group":"brawling","runes":{"potency":0,"property":[],"striking":0,"resilient":0},"damage":{"die":"d6","dice":1,"extra":"","damageType":"B"},"charges":{},"category":"unarmed_attack","material":{},"quantity":1,"image_url":"","is_shoddy":false,"unselectable":true,"source":{"book":"Treasure Vault (Remastered)","page":"106","url":"https://2e.aonprd.com/Companions.aspx?ID=55"}},"operations":[],"content_source_id":16,"version":"1.0","uuid":3341821474558316,"price":{},"traits":[2398,1569],"availability":null},"attack_operation_id":"d85a1f8e-a36b-4c34-ba83-01b58455e3e8","sources":[{"id":1,"name":"Player Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"pathfinder-core","deprecated":null},{"id":3,"name":"Common Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"common-core","deprecated":false},{"id":16,"name":"Treasure Vault","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null}],"dependencies":[{"table":"ability_block","queue_type":"ability-block","id":19856,"expected":{"id":19856,"name":"Strike","uuid":"2549047613995403","content_source_id":3,"type":"action"},"metadata":{},"metadata_absent":["unselectable","deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":40308,"expected":{"id":40308,"name":"Specialized Advancement Selection","uuid":"5849278424911501","content_source_id":1,"type":"feat"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":40304,"expected":{"id":40304,"name":"Mature Advancement","uuid":"8518921942833899","content_source_id":1,"type":"feat"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":40306,"expected":{"id":40306,"name":"Savage Advancement","uuid":"1836159273317102","content_source_id":1,"type":"feat"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":40305,"expected":{"id":40305,"name":"Nimble Advancement","uuid":"1478329439640542","content_source_id":1,"type":"feat"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"ability_block","queue_type":"ability-block","id":40307,"expected":{"id":40307,"name":"Specialized Advancement","uuid":"2450229560164618","content_source_id":1,"type":"feat"},"metadata":{"unselectable":true},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1505,"expected":{"id":1505,"name":"Move","uuid":"5829495615383177","content_source_id":3},"metadata":{},"metadata_absent":["unselectable","deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":2398,"expected":{"id":2398,"name":"Unarmed","uuid":"7327027230694569","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":2448,"expected":{"id":2448,"name":"Ooze","uuid":"6113040896942946","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":1569,"expected":{"id":1569,"name":"Agile","uuid":"8144183238496458","content_source_id":3},"metadata":{},"metadata_absent":["unselectable","deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":2527,"expected":{"id":2527,"name":"Minion","uuid":"8019553394437036","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":3842,"expected":{"id":3842,"name":"Animal Companion","uuid":"8472414784209824","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]},{"table":"trait","queue_type":"trait","id":4173,"expected":{"id":4173,"name":"Reach 10 ft.","uuid":"3411057040924673","content_source_id":3},"metadata":{"unselectable":false},"metadata_absent":["deprecated","hidden"]}],"baseline_counts":{"item":1118,"creature":1,"trait":24},"terminal_counts":{"item":1119,"creature":2,"trait":24},"primary":["https://2e.aonprd.com/Companions.aspx?ID=55","https://2e.aonprd.com/AnimalCompanions.aspx?ID=124","https://2e.aonprd.com/Rules.aspx?ID=2113","https://2e.aonprd.com/Rules.aspx?ID=3417"],"behavior_boundary":"Motion sense and advancement are calculated. Support, Mount and Extend Pseudopod retain printed manual action requirements and temporary effects. No permanent reach or inferred ooze immunity."}$oozeform$::jsonb as spec),
pair as(select spec,(select id from public.item where uuid=(spec#>>'{item,uuid}')::bigint) as item_id,(select id from public.creature where uuid=(spec#>>'{creature,uuid}')::bigint) as creature_id from settings),
expected as(select *, (spec->'item')||jsonb_build_object('uuid',spec#>>'{item,uuid}') as expected_item,
  jsonb_set((spec->'creature')||jsonb_build_object('uuid',spec#>>'{creature,uuid}'),'{operations}',(select jsonb_agg(case when e.value->>'id'=spec->>'attack_operation_id' then jsonb_set(e.value,'{data,itemId}',to_jsonb(item_id)) else e.value end order by e.position) from jsonb_array_elements(spec#>'{creature,operations}') with ordinality e(value,position))) as expected_creature from pair)
select 'treasure-vault-oozeform-chair'::text as id,coalesce((
  item_id is not null and creature_id is not null
  and (select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] from public.item r where r.id=item_id) is not distinct from expected_item
  and (select (to_jsonb(r)||jsonb_build_object('uuid',r.uuid::text))-'{id,created_at,updated_at,search_tsv}'::text[] from public.creature r where r.id=creature_id) is not distinct from expected_creature
  and (select count(*)=3 and bool_and((s.id is not null and jsonb_typeof(s.meta_data::jsonb)='object' and not exists(select 1 from jsonb_each(source_spec) e where to_jsonb(s)->e.key is distinct from e.value)) is true) from jsonb_array_elements(spec->'sources') source_specs(source_spec) left join public.content_source s on s.id=(source_spec->>'id')::bigint)
  and (select s.meta_data::jsonb#>'{counts}' from public.content_source s where s.id=16) @> (spec->'terminal_counts')
  and (select count(*)=13 and bool_and((d.actual is not null and not exists(select 1 from jsonb_each(dependency->'expected') e where d.actual->e.key is distinct from e.value) and not exists(select 1 from jsonb_each(dependency->'metadata') e where d.actual#>array['meta_data',e.key] is distinct from e.value) and not exists(select 1 from jsonb_array_elements_text(dependency->'metadata_absent') k where coalesce(d.actual->'meta_data','{}') ? k)) is true)
    from jsonb_array_elements(spec->'dependencies') deps(dependency) left join lateral (select to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text) as actual from public.ability_block a where dependency->>'table'='ability_block' and a.id=(dependency->>'id')::bigint union all select to_jsonb(t)||jsonb_build_object('uuid',t.uuid::text) from public.trait t where dependency->>'table'='trait' and t.id=(dependency->>'id')::bigint) d on true)
  and not exists(select 1 from public.content_update u where coalesce(u.status->>'state','PENDING') not in ('APPROVED','REJECTED') and (
  (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or u.data->>'name'=s->>'name'))
  or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where u.type=d->>'queue_type' and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{expected,uuid}' or ((u.content_source_id=(d#>>'{expected,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{expected,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{expected,name}')))))
  or (u.type in ('item','creature') and (u.data->>'uuid'=spec#>>array[u.type,'uuid'] or u.ref_id=case when u.type='item' then item_id else creature_id end or u.data->>'id'=case when u.type='item' then item_id::text else creature_id::text end or ((u.content_source_id=16 or u.data->>'content_source_id'='16') and lower(btrim(u.data->>'name'))=lower(btrim(spec#>>array[u.type,'name'])))))
))
),false) as passed from expected
)
select original_checks.id,case when coalesce((status.value->>'recognized')::boolean,true) then coalesce((status.value->>'passed')::boolean,false) else original_checks.passed end as passed from original_checks cross join terminal_status status;
